// Dual-tab session storage check on 8162
const users = [
  { label: 'A', user: '{{ov_privacy:default:viking://~/privacy/credential/deploy_env-huishan-g-dev#/values/username}}', pwd: 'H03W0LoMA6EFQZIW46BnNA==' },
  { label: 'B', user: '300007', pwd: 'H03W0LoMA6EFQZIW46BnNA==' },
]
async function login(u) {
  const res = await fetch('/api/v2.0/security/auth/userLogin', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'zhi-project-id': 'suzhufang' },
    body: JSON.stringify({ username: u.user, password: u.pwd }),
  })
  const body = await res.json()
  const token = body?.data?.accessToken || body?.data?.token
  const name = body?.data?.nickName || body?.data?.userName || u.user
  return { ok: Boolean(token), token, name, user: u.user, code: body?.code, msg: body?.msg }
}
Promise.all(users.map(login)).then((r) => JSON.stringify(r)).catch((e) => JSON.stringify({ error: String(e) }))
